css:
:where(.wtyg-map-site_self_sufficiency){--bg:#0b0e13;--panel:#10151d;--panel2:#171e28;--line:#262f3b;--ink:#e6ebf1;--ink-dim:#8d99a8;--accent:#7fa8d0}
:where(.wtyg-map-site_self_sufficiency) *{box-sizing:border-box}
:where(.wtyg-map-site_self_sufficiency),:where(.wtyg-map-site_self_sufficiency){height:100%;margin:0}
:where(.wtyg-map-site_self_sufficiency){font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;background:var(--bg);color:var(--ink);-webkit-font-smoothing:antialiased}
:where(.wtyg-map-site_self_sufficiency) :is([data-wtyg-id="map"],#wtyg-noid-map){position:absolute;inset:0;height:100vh;background:#0b0e13}
:where(.wtyg-map-site_self_sufficiency) .title{position:absolute;top:14px;left:58px;z-index:600;background:rgba(9,12,17,.8);backdrop-filter:blur(8px);border:1px solid var(--line);border-radius:10px;padding:12px 15px;max-width:420px;max-height:calc(100vh - 28px);overflow-y:auto;box-shadow:0 2px 18px rgba(0,0,0,.35)}
:where(.wtyg-map-site_self_sufficiency) .title h1{margin:0;font-size:13.5px;letter-spacing:.07em;text-transform:uppercase;font-weight:700;line-height:1.3}
:where(.wtyg-map-site_self_sufficiency) .title p{margin:6px 0 0;font-size:11px;color:var(--ink-dim);line-height:1.5}
:where(.wtyg-map-site_self_sufficiency) .title p.scope{margin-top:7px;padding-top:7px;border-top:1px solid var(--line);color:#7c8896;font-size:10px}
:where(.wtyg-map-site_self_sufficiency) .title .mono{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;letter-spacing:0}
:where(.wtyg-map-site_self_sufficiency) .panel{position:absolute;top:14px;right:14px;z-index:600;width:326px;max-width:calc(100vw - 28px);background:rgba(16,21,29,.93);backdrop-filter:blur(8px);border:1px solid var(--line);border-radius:10px;display:flex;flex-direction:column;max-height:calc(100vh - 28px);overflow-y:auto;box-shadow:0 2px 18px rgba(0,0,0,.4)}
:where(.wtyg-map-site_self_sufficiency) .panel::-webkit-scrollbar{width:8px}
:where(.wtyg-map-site_self_sufficiency) .panel::-webkit-scrollbar-thumb{background:#2a3543;border-radius:8px}
:where(.wtyg-map-site_self_sufficiency) .panel .pad{padding:13px 13px 11px;flex:0 0 auto}
:where(.wtyg-map-site_self_sufficiency) .tabbar{display:flex;gap:4px;margin-bottom:11px;background:var(--panel2);border:1px solid var(--line);border-radius:9px;padding:3px}
:where(.wtyg-map-site_self_sufficiency) .tab{flex:1;text-align:center;font-size:11px;font-weight:600;letter-spacing:.02em;color:var(--ink-dim);padding:7px 6px;border-radius:7px;cursor:pointer;user-select:none;transition:background .12s,color .12s;line-height:1.25}
:where(.wtyg-map-site_self_sufficiency) .tab.active{background:var(--accent);color:#0b0e13}
:where(.wtyg-map-site_self_sufficiency) .tab:hover:not(.active){color:var(--ink)}
:where(.wtyg-map-site_self_sufficiency) .subtabbar{display:flex;gap:4px;margin:-4px 0 11px}
:where(.wtyg-map-site_self_sufficiency) .subtab{flex:1;text-align:center;font-size:10px;font-weight:600;color:var(--ink-dim);padding:5px 6px;border-radius:6px;cursor:pointer;user-select:none;border:1px solid var(--line);line-height:1.2}
:where(.wtyg-map-site_self_sufficiency) .subtab.active{background:var(--panel2);color:var(--ink);border-color:#3f5a76}
:where(.wtyg-map-site_self_sufficiency) .subtab:hover:not(.active){color:var(--ink)}
:where(.wtyg-map-site_self_sufficiency) .search{width:100%;background:var(--panel2);border:1px solid var(--line);border-radius:7px;color:var(--ink);padding:9px 11px;font-size:13px;outline:none;transition:border-color .15s}
:where(.wtyg-map-site_self_sufficiency) .search::placeholder{color:#5e6b7a}
:where(.wtyg-map-site_self_sufficiency) .search:focus{border-color:#3f5a76}
:where(.wtyg-map-site_self_sufficiency) .legend{margin-top:11px;display:flex;flex-direction:column;gap:3px}
:where(.wtyg-map-site_self_sufficiency) .leg{display:flex;align-items:center;gap:9px;cursor:pointer;user-select:none;font-size:12px;padding:4px 6px;border-radius:6px;transition:background .12s}
:where(.wtyg-map-site_self_sufficiency) .leg:hover{background:var(--panel2)}
:where(.wtyg-map-site_self_sufficiency) .leg.off{opacity:.38}
:where(.wtyg-map-site_self_sufficiency) .leg .dot{width:10px;height:10px;border-radius:2px;flex:0 0 auto;box-shadow:0 0 0 1px rgba(255,255,255,.18)}
:where(.wtyg-map-site_self_sufficiency) .leg .lab{flex:1;color:var(--ink)}
:where(.wtyg-map-site_self_sufficiency) .leg .cnt{font-family:ui-monospace,monospace;color:var(--ink-dim);font-size:11px}
:where(.wtyg-map-site_self_sufficiency) .togwrap{margin-top:11px;padding-top:10px;border-top:1px solid var(--line)}
:where(.wtyg-map-site_self_sufficiency) .toglab{font-size:10px;letter-spacing:.06em;text-transform:uppercase;color:#6c7785;margin-bottom:7px;font-weight:600}
:where(.wtyg-map-site_self_sufficiency) .togbar{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:4px}
:where(.wtyg-map-site_self_sufficiency) .chip{display:flex;align-items:center;gap:6px;font-size:11px;color:var(--ink);background:var(--panel2);border:1px solid var(--line);border-radius:20px;padding:4px 10px;cursor:pointer;user-select:none;transition:opacity .12s}
:where(.wtyg-map-site_self_sufficiency) .chip.off{opacity:.36}
:where(.wtyg-map-site_self_sufficiency) .chip .sdot{width:9px;height:9px;border-radius:50%;flex:0 0 auto}
:where(.wtyg-map-site_self_sufficiency) .chip .scnt{color:var(--ink-dim);font-family:ui-monospace,monospace;font-size:10px}
:where(.wtyg-map-site_self_sufficiency) .sizenote{font-size:10.5px;color:#5f6b79;margin-top:11px;line-height:1.5}
:where(.wtyg-map-site_self_sufficiency) .meta{display:flex;justify-content:space-between;align-items:center;font-size:11px;color:var(--ink-dim);margin-top:10px;padding-top:9px;border-top:1px solid var(--line)}
:where(.wtyg-map-site_self_sufficiency) .meta a{color:var(--accent);text-decoration:none;cursor:pointer}
:where(.wtyg-map-site_self_sufficiency) .meta a:hover{color:#a9c8e6}
:where(.wtyg-map-site_self_sufficiency) .scrollbody{overflow:auto;border-top:1px solid var(--line);flex:1 1 auto;min-height:42vh}
:where(.wtyg-map-site_self_sufficiency) .scrollbody::-webkit-scrollbar{width:8px}
:where(.wtyg-map-site_self_sufficiency) .scrollbody::-webkit-scrollbar-thumb{background:#2a3543;border-radius:8px}
:where(.wtyg-map-site_self_sufficiency) .excl{margin-top:9px;padding-top:9px;border-top:1px solid var(--line)}
:where(.wtyg-map-site_self_sufficiency) .excl summary{font-size:10.5px;color:#8d99a8;cursor:pointer;list-style:none;font-weight:600;letter-spacing:.02em}
:where(.wtyg-map-site_self_sufficiency) .excl summary::-webkit-details-marker{display:none}
:where(.wtyg-map-site_self_sufficiency) .excl summary::before{content:"\25B8  ";color:#5f6b79}
:where(.wtyg-map-site_self_sufficiency) .excl[open] summary::before{content:"\25BE  "}
:where(.wtyg-map-site_self_sufficiency) .excl .body{font-size:10px;color:#6c7785;line-height:1.55;margin-top:7px}
:where(.wtyg-map-site_self_sufficiency) .excl .body b{color:#8d99a8;font-weight:600}
:where(.wtyg-map-site_self_sufficiency) .listhdr{position:sticky;top:0;z-index:2;background:rgba(16,21,29,.97);font-size:10px;letter-spacing:.06em;text-transform:uppercase;color:#8d99a8;font-weight:600;padding:8px 12px;border-bottom:1px solid var(--line)}
:where(.wtyg-map-site_self_sufficiency) .list{padding:6px 6px 9px}
:where(.wtyg-map-site_self_sufficiency) .row{display:flex;gap:9px;align-items:flex-start;padding:7px 8px;border-radius:7px;cursor:pointer;transition:background .12s}
:where(.wtyg-map-site_self_sufficiency) .row:hover{background:var(--panel2)}
:where(.wtyg-map-site_self_sufficiency) .row .rk{font-family:ui-monospace,monospace;font-size:11px;color:var(--ink-dim);min-width:22px;text-align:right;margin-top:1px}
:where(.wtyg-map-site_self_sufficiency) .row .bar{width:3px;align-self:stretch;border-radius:2px;flex:0 0 auto;margin-top:1px}
:where(.wtyg-map-site_self_sufficiency) .row .nm{font-size:12.5px;line-height:1.3;font-weight:600}
:where(.wtyg-map-site_self_sufficiency) .row .sub{font-size:10.5px;color:var(--ink-dim);margin-top:2px;line-height:1.35}
:where(.wtyg-map-site_self_sufficiency) .row .sub .mono{font-family:ui-monospace,monospace}
:where(.wtyg-map-site_self_sufficiency) .row .sd{display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:5px;vertical-align:baseline}
:where(.wtyg-map-site_self_sufficiency) .grp{margin:1px 0}
:where(.wtyg-map-site_self_sufficiency) .grphdr{display:flex;align-items:center;gap:8px;padding:7px 10px 7px 8px;margin:5px 6px 1px;cursor:pointer;user-select:none;border-radius:6px;background:var(--panel2);font-size:11px;font-weight:600;letter-spacing:.02em;transition:background .12s}
:where(.wtyg-map-site_self_sufficiency) .grphdr:hover{background:#1d2632}
:where(.wtyg-map-site_self_sufficiency) .grphdr::before{content:"\25BE";color:#5f6b79;font-size:9px;width:10px;flex:0 0 auto;text-align:center}
:where(.wtyg-map-site_self_sufficiency) .grp.collapsed .grphdr::before{content:"\25B8"}
:where(.wtyg-map-site_self_sufficiency) .grphdr .gdot{width:9px;height:9px;border-radius:2px;flex:0 0 auto;box-shadow:0 0 0 1px rgba(255,255,255,.18)}
:where(.wtyg-map-site_self_sufficiency) .grphdr .glab{flex:1;color:var(--ink)}
:where(.wtyg-map-site_self_sufficiency) .grphdr .gcnt{font-family:ui-monospace,monospace;color:var(--ink-dim);font-size:10.5px}
:where(.wtyg-map-site_self_sufficiency) .grp.collapsed .grpbody{display:none}
:where(.wtyg-map-site_self_sufficiency) .grpbody{padding:1px 0 3px}
:where(.wtyg-map-site_self_sufficiency) .filterhint{font-size:9.5px;color:#5f6b79;margin:7px 0 0;line-height:1.4}
:where(.wtyg-map-site_self_sufficiency) .leaflet-pane path.mk{filter:drop-shadow(0 1px 2px rgba(0,0,0,.55))}
:where(.wtyg-map-site_self_sufficiency) .leaflet-popup-content-wrapper{background:var(--panel);color:var(--ink);border-radius:10px;border:1px solid var(--line);box-shadow:0 6px 26px rgba(0,0,0,.5)}
:where(.wtyg-map-site_self_sufficiency) .leaflet-popup-tip{background:var(--panel);border:1px solid var(--line)}
:where(.wtyg-map-site_self_sufficiency) .leaflet-popup-content{margin:12px 14px;font-size:12.5px;line-height:1.5;min-width:252px}
:where(.wtyg-map-site_self_sufficiency) .pop h3{margin:0 0 2px;font-size:14px;line-height:1.3;font-weight:700}
:where(.wtyg-map-site_self_sufficiency) .pop .rkbig{font-family:ui-monospace,monospace;font-size:10.5px;color:var(--ink-dim);letter-spacing:.04em;text-transform:uppercase}
:where(.wtyg-map-site_self_sufficiency) .pop .tags{margin:7px 0 8px;display:flex;gap:5px;flex-wrap:wrap}
:where(.wtyg-map-site_self_sufficiency) .pop .tag{display:inline-block;font-size:9.5px;letter-spacing:.05em;text-transform:uppercase;padding:3px 8px;border-radius:4px;font-weight:700;color:#0b0e13}
:where(.wtyg-map-site_self_sufficiency) .pop .kv{margin:3px 0}
:where(.wtyg-map-site_self_sufficiency) .pop .kv b{color:var(--ink-dim);font-weight:600}
:where(.wtyg-map-site_self_sufficiency) .pop .desc{margin-top:8px;padding-top:7px;border-top:1px solid var(--line);color:#dbe2ea;font-size:12.5px;line-height:1.55}
:where(.wtyg-map-site_self_sufficiency) .pop .today{margin-top:8px;color:#c4cedb;font-size:12px;line-height:1.5}
:where(.wtyg-map-site_self_sufficiency) .pop .today b{color:var(--accent);font-weight:600}
:where(.wtyg-map-site_self_sufficiency) .leaflet-bar a{background:#171e28;color:#e6ebf1;border-bottom:1px solid var(--line)}
:where(.wtyg-map-site_self_sufficiency) .leaflet-bar a:hover{background:#222c39}
:where(.wtyg-map-site_self_sufficiency) .leaflet-control-attribution{background:rgba(9,12,17,.72)!important;color:#6c7785!important;font-size:10px!important}
:where(.wtyg-map-site_self_sufficiency) .leaflet-control-attribution a{color:#8fa9c2!important}
:where(.wtyg-map-site_self_sufficiency) .leaflet-control-layers{background:rgba(16,21,29,.96)!important;color:var(--ink)!important;border:1px solid var(--line)!important;border-radius:8px!important}
:where(.wtyg-map-site_self_sufficiency) .leaflet-control-layers-expanded{padding:9px 11px!important}
@media (max-width:640px){:where(.wtyg-map-site_self_sufficiency) .title{left:58px;max-width:calc(100vw - 72px);padding:9px 11px}
:where(.wtyg-map-site_self_sufficiency) .title h1{font-size:12px}
:where(.wtyg-map-site_self_sufficiency) .panel{width:calc(100vw - 28px);top:auto;bottom:14px;right:14px;max-height:48vh}}
